<body>
    <div class="canvas-container">
        <canvas id="star-canvas"></canvas>
    </div>

    <div class="ui-layer">
        <div class="pulse-ring"></div>

        <div class="header">
            <h1>Abyssal Nebula</h1>
            <p>// Interactive Immersive Experience //</p>
        </div>

        <div class="hud-overlay">
            <span class="hud-text">Mouse: Move to Interact | Click to Create Constellations</span>
        </div>

        <div class="controls">
            <button class="control-btn" id="btn-reset" title="Reset View">⟳</button>
            <button class="control-btn" id="btn-pause" title="Pause/Resume">⏸</button>
            <button class="control-btn" id="btn-info" title="Info Panel">ℹ️</button>
        </div>

        <div class="info-panel" id="infoPanel">
            <h2>About This Experience</h2>
            <p>Welcome to the Abyssal Nebula — an interactive cosmic journey. Move your mouse through the starfield, click to create constellations, and experience a mesmerizing blend of particles, gradients, and subtle motion physics.</p>
            <br>
            <p><strong>Controls:</strong></p>
            <ul style="margin-left: 1.5rem; color: rgba(232, 244, 255, 0.7);">
                <li>Move mouse to interact with particle field</li>
                <li>Click anywhere to create star constellations</li>
                <li>Use the right-side buttons to control the experience</li>
            </ul>
        </div>

        <div class="title-reveal" id="titleReveal">ABYSSAL NEBULA</div>
    </div>

    <!-- Embedded Visual Asset -->
    <img src="assets/hero.png" data-generate="A breathtaking view of a deep space nebula with swirling clouds of violet, blue, and magenta cosmic dust. Stars scattered throughout creating depth, subtle glowing particles drifting in the background, cinematic lighting with volumetric haze effects. The composition should feel mysterious and immersive." alt="Hero Nebula Background">

    <script>
        // Canvas Setup
        const canvas = document.getElementById('star-canvas');
        const ctx = canvas.getContext('2d');

        let width, height;
        let particles = [];
        let constellationParticles = [];
        let mouseX = 0, mouseY = 0;
        let mouseSpeed = 0;
        let time = 0;
        let paused = false;

        // Resize handling
        function resize() {
            width = canvas.width = window.innerWidth;
            height = canvas.height = window.innerHeight;
        }

        window.addEventListener('resize', () => { resize(); });
        resize();

        // Mouse tracking with smooth follow
        document.body.addEventListener('mousemove', (e) => {
            mouseX = e.clientX;
            mouseY = e.clientY;
            mouseSpeed = Math.min(30, 15 + Math.abs(mouseX - window.innerWidth / 2));

            const xDiff = mouseX - width / 2;
            const yDiff = mouseY - height / 2;
            document.body.style.transform = `translate(${xDiff * 0.3}px, ${yDiff * 0.3}px)`;
        });

        // Click to create constellation star
        canvas.addEventListener('click', () => {
            if (!paused) {
                const x = Math.random() * width + (Math.random() - 0.5) * 100;
                const y = Math.random() * height + (Math.random() - 0.5) * 100;

                constellationParticles.push({
                    x: x,
                    y: y,
                    vx: (Math.random() - 0.5) * 2,
                    vy: (Math.random() - 0.5) * 2,
                    size: Math.random() * 3 + 1,
                    color: `hsl(${Math.random() * 60 + 200}, ${70}%, ${40}%)`
                });

                // Reveal title on first click
                if (particles.length < 500) {
                    document.getElementById('titleReveal').classList.add('active');
                    document.getElementById('infoPanel').classList.add('active');
                }
            }
        });

        // Particle classes
        class StarParticle {
            constructor() {
                this.reset();
            }

            reset() {
                this.x = Math.random() * width;
                this.y = Math.random() * height;
                this.size = Math.random() < 0.7 ? 1 : 2;
                this.baseSize = this.size;
                this.alpha = Math.random() * 0.5 + 0.3;
                this.velocityX = (Math.random() - 0.5) * 0.5;
                this.velocityY = (Math.random() - 0.5) * 0.5;
                this.driftSpeed = Math.random() < 0.7 ? 0.01 : 0.02;
                this.color = `hsl(${Math.random() * 60 + 200}, ${70}%, ${40 + Math.random() * 10}%)`;
            }

            update() {
                if (paused) return;

                // Mouse repulsion effect
                const dx = mouseX - this.x;
                const dy = mouseY - this.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist < 200) {
                    const force = (200 - dist) / 200;
                    this.velocityX -= dx * 0.01 * force;
                    this.velocityY -= dy * 0.01 * force;
                }

                this.x += this.velocityX + (mouseSpeed * 0.3);
                this.y += this.velocityY;

                // Wrap around edges
                if (this.x < -50) { this.x = width + 50; }
                if (this.x > width + 50) { this.x = -50; }
                if (this.y < -50) { this.y = height + 50; }
                if (this.y > height + 50) { this.y = -50; }

                // Subtle breathing effect
                const breath = Math.sin(time * 2) * 0.1;
                this.size = this.baseSize + breath;
            }

            draw() {
                ctx.save();
                ctx.globalAlpha = this.alpha;
                ctx.fillStyle = this.color;

                // Create glow effect for larger particles
                const gradient = ctx.createRadialGradient(
                    this.x, this.y, 0,
                    this.x, this.y, this.size * 3
                );
                gradient.addColorStop(0, 'white');
                gradient.addColorStop(0.5, this.color);
                gradient.addColorStop(1, 'transparent');

                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size * 3, 0, Math.PI * 2);
                ctx.fillStyle = gradient;
                ctx.fill();

                // Core star
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fillStyle = 'white';
                ctx.fill();

                ctx.restore();
            }
        }

        class ConstellationParticle {
            constructor() {
                this.reset();
            }

            reset() {
                this.x = Math.random() * width;
                this.y = Math.random() * height;
                this.vx = (Math.random() - 0.5) * 2;
                this.vy = (Math.random() - 0.5) * 2;
                this.size = Math.random() < 0.7 ? 3 : 5;
                this.baseSize = this.size;
                this.alpha = Math.random() * 0.8 + 0.4;
                this.color = `hsl(${Math.random() * 60 + 200}, ${70}%, ${40}%)`;
            }

            update() {
                if (paused) return;

                const dx = mouseX - this.x;
                const dy = mouseY - this.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist < 300) {
                    const force = (300 - dist) / 300 * 0.5;
                    this.vx -= dx * 0.02 * force;
                    this.vy -= dy * 0.02 * force;
                }

                this.x += this.vx;
                this.y += this.vy;

                if (this.x < -100) { this.x = width + 100; }
                if (this.x > width + 100) { this.x = -100; }
                if (this.y < -100) { this.y = height + 100; }
                if (this.y > height + 100) { this.y = -100; }

                const breath = Math.sin(time * 3) * 0.2;
                this.size = this.baseSize + breath;
            }

            draw() {
                ctx.save();
                ctx.globalAlpha = this.alpha;
                ctx.fillStyle = this.color;

                // Larger glow for constellation stars
                const gradient = ctx.createRadialGradient(
                    this.x, this.y, 0,
                    this.x, this.y, this.size * 4
                );
                gradient.addColorStop(0, 'white');
                gradient.addColorStop(0.3, this.color);
                gradient.addColorStop(1, 'transparent');

                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size * 4, 0, Math.PI * 2);
                ctx.fillStyle = gradient;
                ctx.fill();

                // Core star with shine effect
                const shineX = this.x + Math.sin(time) * (this.size / 2);
                const shineY = this.y + Math.cos(time * 1.5) * (this.size / 2);

                ctx.beginPath();
                ctx.arc(shineX, shineY, this.size / 3, 0, Math.PI * 2);
                ctx.fillStyle = 'white';
                ctx.shadowBlur = 10;
                ctx.shadowColor = 'white';
                ctx.fill();
                ctx.shadowBlur = 0;

                ctx.restore();
            }
        }

        // Initialize particles
        function initParticles() {
            particles.length = 0;
            constellationParticles.length = 0;

            const particleCount = Math.min(600, width * height / 8000);

            for (let i = 0; i < particleCount; i++) {
                particles.push(new StarParticle());
            }

            // Add some constellation stars initially
            for (let i = 0; i < 30; i++) {
                if (Math.random() < 0.5) {
                    constellationParticles.push(new ConstellationParticle());
                }
            }
        }

        initParticles();

        // Animation loop
        function animate() {
            const gradient = ctx.createLinearGradient(0, 0, width, height);
            gradient.addColorStop(0, '#0a0a1a');
            gradient.addColorStop(0.5, '#1a1a2e');
            gradient.addColorStop(1, '#0f0f23');

            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, width, height);

            // Draw constellation stars first (they should appear more prominent)
            constellationParticles.forEach(p => {
                p.update();
                p.draw();
            });

            // Draw regular star particles with depth effect based on position
            particles.slice().sort((a, b) => a.y - b.y).forEach(p => {
                p.update();
                p.draw();
            });

            // Subtle background glow animation
            time += 0.01;

            const hue = (time * 3) % 360;
            const gradient2 = ctx.createRadialGradient(
                width * 0.3, height * 0.3, 0,
                width * 0.5, height * 0.5, width
            );

            const blue1 = `hsla(${hue}, ${60}%, ${20}%)`;
            const blue2 = `hsla(${hue + 40}, ${50}%, ${10}%)`;

            gradient2.addColorStop(0, 'transparent');
            gradient2.addColorStop(0.3, blue1);
            gradient2.addColorStop(0.7, blue2);
            gradient2.addColorStop(1, 'transparent');

            ctx.globalAlpha = 0.05;
            ctx.fillStyle = gradient2;
            ctx.fillRect(0, 0, width, height);
            ctx.globalAlpha = 1;

            requestAnimationFrame(animate);
        }

        animate();

        // Button handlers
        document.getElementById('btn-reset').addEventListener('click', () => {
            initParticles();
        });

        document.getElementById('btn-pause').addEventListener('click', (e) => {
            e.stopPropagation();
            paused = !paused;
        });

        document.getElementById('btn-info').addEventListener('click', (e) => {
            e.stopPropagation();
            document.getElementById('infoPanel').classList.toggle('active');
        });

        // Keyboard navigation support
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                document.getElementById('infoPanel').classList.remove('active');
            }
        });
    </script>
</body>
</html>
